function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function navItem(page,label,icon){return `<button class="nav-item ${(state.page===page || page==='templates'&&state.page==='setup')?'active':''}" data-action="navigate" data-page="${page}">${ico(icon)}<span class="nav-text">${label}</span></button>`;}
function render(){
  const activeElement=document.activeElement;
  const focusId=activeElement?.id;
  const selection=typeof activeElement?.selectionStart==='number'?[activeElement.selectionStart,activeElement.selectionEnd]:null;
  const navigation=navItem('home','Tổng quan','home')+navItem('experts','Chuyên gia AI','expert')+navItem('templates','Discussion mới','chat')+navItem('library','Case Library','book');
  $('#app').innerHTML=`<div class="shell variant-${state.variant}"><aside class="sidebar"><div class="logo"><span class="logo-mark"></span><span class="logo-text">DPrism</span></div><div class="nav-section">WORKSPACE</div>${navigation}<div class="sidebar-foot row"><span class="avatar">TR</span><div><strong class="small">Tran</strong><p class="muted" style="font-size:10px">Personal workspace</p></div></div></aside><div class="body-area"><header class="topbar">${state.variant==='B'?`<div class="logo"><span class="logo-mark"></span><span>DPrism</span></div><nav class="top-nav" aria-label="Điều hướng">${navigation}</nav>`:`<div class="breadcrumb">Workspace <span style="margin:0 8px">/</span> <span>${pageNames[state.page]}</span></div><div class="logo mobile-logo" style="display:none"><span class="logo-mark"></span><span>DPrism</span></div>`}<div class="topbar-right"><span class="mode-label">FRONTEND PROTOTYPE</span><span class="row small muted">${ico('globe')} VI</span><span class="avatar" style="height:30px;width:30px;font-size:10px;border-radius:50%">TR</span></div></header><main class="main" id="main-content">${renderPage()}</main></div></div>`;
  renderTools();
  if(focusId){const el=document.getElementById(focusId);if(el){el.focus({preventScroll:true});if(selection&&el.setSelectionRange)try{el.setSelectionRange(...selection);}catch{}}}
}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><div class="between"><h1>${title}</h1>${action}</div>${description?`<p>${description}</p>`:''}</div>`;}
function renderPage(){
  if(state.page==='home')return renderHome();
  if(state.page==='experts')return renderExperts();
  if(state.page==='templates')return renderTemplates();
  if(state.page==='setup')return renderSetup();
  if(state.page==='running')return renderRunning();
  if(state.page==='dashboard')return renderDashboard();
  return renderLibrary();
}
function renderHome(){return `<div class="welcome"><div class="welcome-intro"><div class="eyebrow">EXPERTISE, WORKING TOGETHER</div><h1>Chào Tran, hôm nay bạn muốn làm gì?</h1><p>Tạo expert theo cách bạn cần. Kết hợp chuyên môn thành một plan rõ ràng.</p></div><div class="grid2"><section class="card welcome-card"><div class="big-icon">${ico('expert')}</div><h2>Tạo chuyên gia AI</h2><p>Định nghĩa chuyên môn, cách tư duy và skills. Expert không cần mang danh tính một người thật.</p><div class="row wrap">${badge('Vai trò chuyên môn')}${badge('System instructions')}${badge('Skills')}</div>${btn('Khám phá & tạo expert '+ico('arrow'),'navigate','primary','data-page="experts"')}</section><section class="card welcome-card"><div class="big-icon">${ico('chat')}</div><h2>Cùng expert giải quyết vấn đề</h2><p>Chọn template hoặc bắt đầu từ một chủ đề. Kiểm tra plan, rồi nhận kết quả có nguồn tham khảo và trace.</p><div class="row wrap">${badge('Plan có cấu trúc')}${badge('Giữ lại bất đồng')}</div>${btn('Tạo discussion '+ico('arrow'),'navigate','primary','data-page="templates"')}</section></div><div class="between welcome-foot"><span>${experts.length} expert sẵn sàng · ${templates.length} template mẫu</span><button class="text-button" data-action="navigate" data-page="library">Khám phá case đã chia sẻ →</button></div><div class="notice">${ico('bulb')} Prototype chỉ trình diễn luồng giao diện. Dữ liệu nằm trong bộ nhớ và được đặt lại khi tải lại trang.</div>${state.sessions.length?`<section class="card gap"><h3>Phiên vừa thực hiện</h3>${state.sessions.map((r,i)=>`<div class="between tiny-gap"><span class="small">${esc(r.plan.title)}</span>${btn('Xem kết quả','session','small',`data-index="${i}"`)}</div>`).join('')}</section>`:''}</div>`;}
function renderExperts(){
  const list=experts.filter(e=>(e.role+' '+e.domain).toLowerCase().includes(state.expertQuery.toLowerCase())&&(state.expertDomain==='all'||e.domain===state.expertDomain));
  return heading('EXPERT WORKSPACE','Chuyên môn bắt đầu từ đây.','Tạo và tổ chức expert theo vai trò. Chọn kỹ năng phù hợp với cách bạn muốn vấn đề được đánh giá.',btn(ico('plus')+' Tạo expert','new-expert','primary'))+`<div class="library-toolbar"><div class="search-box">${ico('search')}<input id="expert-search" data-field="expertQuery" value="${esc(state.expertQuery)}" placeholder="Tìm theo chuyên môn hoặc lĩnh vực…" aria-label="Tìm expert"></div><select style="max-width:200px" data-action-change="domain" aria-label="Lĩnh vực"><option value="all">Tất cả lĩnh vực</option>${[...new Set(experts.map(e=>e.domain))].map(d=>`<option ${d===state.expertDomain?'selected':''}>${esc(d)}</option>`).join('')}</select><span class="small muted">${list.length} expert</span></div><div class="grid3">${list.map(e=>`<article class="card expert-card"><div class="between">${avatar(e)}${badge(e.domain,e.color==='purple'?'purple':'')}</div><h3>${esc(e.role)}</h3><p>${esc(e.approach)}</p><div class="row wrap">${e.skills.map(s=>badge(s)).join('')}</div><div class="expert-footer"><span class="small muted">${e.skills.length} skills · chưa có KB</span><button class="text-button" data-action="expert-profile" data-id="${e.id}">Xem & chỉnh sửa →</button></div></article>`).join('')||'<div class="empty">Không có expert phù hợp.</div>'}</div>`;
}
function renderTemplates(){return heading('NEW DISCUSSION','Một mục tiêu. Một plan rõ ràng.','Chọn quy trình có sẵn hoặc để hệ thống đề xuất plan từ vấn đề của bạn.')+`<div class="between section-title"><h3>Template dựng sẵn</h3><span class="small muted">Có thể điều chỉnh trước khi Start</span></div><div class="grid2">${templates.map(t=>`<button class="card template-card" data-action="use-template" data-id="${t.id}"><div class="between"><div class="avatar">${ico(t.icon)}</div>${badge(t.tag,'red')}</div><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p><div class="template-footer between"><span>${t.steps} bước · ${esc(t.output)}</span>${ico('arrow')}</div></button>`).join('')}</div><div class="grid2 gap"><button class="card path-card" data-action="describe-template"><span class="avatar purple">${ico('search')}</span><div class="grow"><h3>Chưa tìm thấy template phù hợp?</h3><p>Mô tả vấn đề để tìm template; tự tạo mới nếu không có lựa chọn phù hợp.</p></div>${ico('arrow')}</button><button class="card path-card" data-action="open-discussion"><span class="avatar blue">${ico('chat')}</span><div class="grow"><h3>Bắt đầu không dùng template</h3><p>Nhập chủ đề và đầu ra; xem đề xuất plan riêng cho discussion này.</p></div>${ico('arrow')}</button></div>`;}
function stepper(){return `<nav class="stepper" aria-label="Các bước chuẩn bị">${['Bối cảnh','Case liên quan','Plan & đầu ra','Review & start'].map((s,i)=>`${i?'<div class="stepper-line"></div>':''}<button class="stepper-item ${state.wizard===i+1?'active':state.wizard>i+1?'complete':''}" data-action="wizard-goto" data-step="${i+1}" ${i+1>state.wizard?'disabled':''}><span class="step-dot">${i+1<state.wizard?'✓':i+1}</span><span>${s}</span></button>`).join('')}</nav>`;}
function wizardFooter(back,next,action='wizard-next'){return `<div class="wizard-foot">${btn(ico('back')+' '+back,'wizard-back')}<span class="muted small">${state.mode==='open'?'Plan riêng · không bắt buộc lưu template':'Bản riêng của discussion · template gốc không đổi'}</span>${btn(next+' '+ico('arrow'),action,'primary')}</div>`;}
function renderSetup(){return stepper()+(state.wizard===1?renderContext():state.wizard===2?renderSimilar():state.wizard===3?renderPlan():renderReview());}
function renderContext(){
  const starFields=[['situation','S','Situation','Bối cảnh hiện tại là gì?'],['task','T','Task','Bạn cần giải quyết hoặc quyết định gì?'],['action','A','Action','Đã thử gì? Có lựa chọn và ràng buộc nào?'],['result','R','Result','Đầu ra và tiêu chí thành công là gì?']];
  return heading('01 / CONTEXT','Mô tả vấn đề','Hồ sơ rõ ràng giúp expert phân biệt dữ kiện, giả định và thông tin còn thiếu.')+`<section class="card"><div class="field"><label class="label" for="discussion-title">Tên discussion</label><input id="discussion-title" data-field="title" value="${esc(state.title)}"></div>${starFields.map(([key,letter,title,desc])=>`<div class="star-field"><span class="star-letter">${letter}</span><div><h3>${title}</h3><p>${desc}</p></div><textarea id="star-${key}" data-star="${key}" aria-label="${title}">${esc(state.star[key])}</textarea></div>`).join('')}<div class="field"><label class="label" for="initial-output">Đầu ra mong muốn</label><textarea id="initial-output" data-field="output">${esc(state.output)}</textarea></div><div class="divider"></div><div class="between section-title"><h3>Tài liệu hồ sơ</h3><span class="small muted">Gán tài liệu cho từng bước tại màn Plan</span></div><div class="row wrap">${state.discussionDocs.map(id=>docChip(id)).join('')}</div><div class="upload-zone tiny-gap"><label class="label" for="document-upload">${ico('file')} Thêm tài liệu từ máy</label><input id="document-upload" type="file" accept=".txt,.md,.pdf,.docx,.csv" multiple><p class="muted small tiny-gap">TXT/MD/CSV được đọc cục bộ; PDF/DOCX chỉ minh họa tên file, chưa trích xuất nội dung.</p></div>${state.mode==='find'?renderRecommendations():''}${wizardFooter('Chọn cách bắt đầu',state.mode==='find'&&!state.recommendations?'Tìm template phù hợp':'Tiếp tục')}</section>`;
}
function docChip(id){const d=currentDocument(id);return d?`<span class="doc-chip">${ico('file')} ${esc(d.name)}<button class="text-button" data-action="document" data-id="${d.id}" aria-label="Xem ${esc(d.name)}">Xem</button></span>`:'';}
function renderRecommendations(){if(!state.recommendations)return '';return `<section class="gap"><div class="notice">Đề xuất dưới đây là dữ liệu mẫu để thử luồng lựa chọn template.</div><div class="grid2 tiny-gap">${templates.map(t=>`<button class="card template-card" data-action="recommended-template" data-id="${t.id}"><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><span class="text-button">Chọn template →</span></button>`).join('')}</div><button class="text-button gap" data-action="custom-template">Không có template phù hợp — tự tạo template mới →</button></section>`;}
function renderSimilar(){return heading('02 / RELATED CASES','Không bắt đầu từ một trang trắng.','Chỉ hiển thị case đã được chủ sở hữu chia sẻ. Chọn case để đưa vào context; có thể bỏ qua bước này.')+`<div class="notice section-title"><strong>Vấn đề của bạn:</strong> ${esc(state.star.task)}</div><div class="stack">${cases.filter(c=>c.public).map(c=>`<article class="card case-card ${state.selectedCases.includes(c.id)?'selected':''}"><div class="case-check">${state.selectedCases.includes(c.id)?'✓':''}</div><div class="grow"><div class="row wrap">${badge('Đã chia sẻ toàn bộ','green')}${badge('AutoSupport')}</div><h3 class="tiny-gap">${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="case-meta">${esc(c.owner)} · ${c.date}</div></div><div class="stack" style="gap:8px">${btn('Xem toàn bộ case','case','small',`data-id="${c.id}"`)}${btn(state.selectedCases.includes(c.id)?'Đã chọn ✓':'Dùng làm context','toggle-case',state.selectedCases.includes(c.id)?'small subtle':'small primary',`data-id="${c.id}"`)}</div></article>`).join('')}</div><div class="notice gap">Case được chọn là tài liệu tham khảo từ phiên trước. Trong cùng một bước mới, các expert vẫn đưa ra đánh giá ban đầu độc lập.</div>${wizardFooter('Bối cảnh',state.mode==='open'?'Xem plan đề xuất':'Cấu hình plan')}`;}
function planHeader(){return `<div class="plan-top"><div class="card"><div class="row wrap">${badge(state.mode==='open'?'Đề xuất plan · dữ liệu mẫu':state.mode==='custom'?'Template mới · bản nháp':'Plan riêng từ template','red')}${badge('Chỉnh sửa trước Start')}</div><h2 class="tiny-gap">${esc(state.title)}</h2><p class="small muted tiny-gap">Bấm một bước để xem expert, tài liệu, đầu vào và đầu ra. Mũi tên thể hiện phụ thuộc.</p></div><div class="card plan-stats"><div><strong>${state.steps.length}</strong><span>Bước</span></div><div><strong>${selectedExpertCount()}</strong><span>Expert</span></div><div><strong>${state.selectedCases.length}</strong><span>Case</span></div></div></div>`;}
function validatePlan(){
  if(!state.title.trim()||!state.output.trim())return 'Cần tên discussion và đầu ra mong muốn.';
  if(!state.steps.length)return 'Plan cần ít nhất một bước.';
  const ids=new Set(state.steps.map(s=>s.id));
  for(const s of state.steps){if(!s.title.trim()||!s.output.trim()||!s.experts.length)return `${s.id}: cần tên bước, đầu ra và ít nhất một expert.`;if(s.depends.some(id=>!ids.has(id)||id===s.id))return `${s.id}: phụ thuộc không hợp lệ.`;if(s.experts.length>1&&s.rounds<1)return `${s.id}: cần ít nhất một vòng trao đổi tối đa khi có nhiều expert.`;if(!Number.isInteger(s.rounds)||s.rounds<0||s.rounds>5||!Number.isFinite(s.budget)||s.budget<100)return `${s.id}: vòng trao đổi phải từ 0–5; token budget ít nhất 100.`;}
  const visiting=new Set(),visited=new Set();
  function visit(id){if(visiting.has(id))return false;if(visited.has(id))return true;visiting.add(id);for(const dep of stepById(id).depends)if(!visit(dep))return false;visiting.delete(id);visited.add(id);return true;}
  return state.steps.every(s=>visit(s.id))?'':'Phụ thuộc tạo thành chu trình. Hãy bỏ một liên kết trước khi tiếp tục.';
}
function planDepths(){const depths={};function depth(s,path=[]){if(path.includes(s.id))return 0;if(depths[s.id]!==undefined)return depths[s.id];return depths[s.id]=s.depends.length?1+Math.max(...s.depends.map(id=>{const dep=stepById(id);return dep?depth(dep,[...path,s.id]):0;})):0;}state.steps.forEach(s=>depth(s));return depths;}
function renderDAG(){
  const depths=planDepths(),groups={};state.steps.forEach(s=>(groups[depths[s.id]]??=[]).push(s));
  const maxDepth=Math.max(0,...Object.values(depths)),maxRows=Math.max(1,...Object.values(groups).map(g=>g.length));
  const width=Math.max(650,(maxDepth+1)*230+20),height=Math.max(300,maxRows*150+20),positions={};
  Object.entries(groups).forEach(([depth,steps])=>steps.forEach((s,i)=>positions[s.id]={x:20+Number(depth)*230,y:(height-steps.length*145)/2+i*145}));
  const edges=state.steps.flatMap(s=>s.depends.map(dep=>{const a=positions[dep],b=positions[s.id];if(!a||!b)return '';const x=a.x+190,y=a.y+57,x2=b.x,y2=b.y+57;return `<path d="M${x},${y} C${x+35},${y} ${x2-35},${y2} ${x2},${y2}" fill="none" stroke="#b9c5d7" stroke-width="1.5" marker-end="url(#dag-arrow)"/>`;})).join('');
  return `<section class="card plan-canvas"><div class="canvas-toolbar"><strong class="row">${ico('graph')} Plan DAG</strong>${btn(ico('plus')+' Thêm bước','add-step','small')}</div>${state.validation?`<div class="plan-error">${esc(state.validation)}</div>`:''}<div class="dag-scroll"><div class="dag-scene" style="width:${width}px;min-height:${height}px"><svg class="edges" style="width:${width}px;height:${height}px" viewBox="0 0 ${width} ${height}" aria-label="Các liên kết phụ thuộc"><defs><marker id="dag-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7z" fill="#b9c5d7"/></marker></defs>${edges}</svg>${state.steps.map(s=>`<button class="dag-node ${s.id===state.selectedStep?'selected':''}" style="left:${positions[s.id].x}px;top:${positions[s.id].y}px" data-action="select-step" data-id="${s.id}"><div class="between"><span class="node-number">${s.id}</span>${badge(s.experts.length>1?`${s.rounds} vòng tối đa`:'Single expert',s.experts.length>1?'red':'')}</div><h3>${esc(s.title)}</h3><div class="node-meta">${miniatureExperts(s.experts)}<span>${s.docs.length} tài liệu</span></div></button>`).join('')}</div></div><div class="canvas-legend"><span><i></i> Bước đang chọn</span><span>→ Phụ thuộc kết quả đã hoàn tất</span><span>Cuộn ngang để xem toàn bộ</span></div></section>`;
}
function renderInspector(){
  const s=stepById(state.selectedStep)||state.steps[0];if(!s)return '';
  return `<aside class="card inspector"><div class="between section-title"><div><div class="eyebrow">STEP ${s.id}</div><h3>Chi tiết bước</h3></div>${btn(ico('close'),'remove-step','icon-btn small',`data-id="${s.id}" title="Xóa bước" ${state.steps.length===1?'disabled':''}`)}</div><div class="field"><label class="label" for="step-title">Tên bước</label><input id="step-title" data-step-field="title" value="${esc(s.title)}"></div><div class="field"><label class="label" for="step-instruction">Yêu cầu thực hiện</label><textarea id="step-instruction" data-step-field="instruction">${esc(s.instruction)}</textarea></div><div class="field"><label class="label" for="step-output">Đầu ra của bước</label><textarea id="step-output" data-step-field="output">${esc(s.output)}</textarea></div><div class="inspector-group"><h3>Expert được giao</h3>${experts.map(e=>`<label class="expert-option">${avatar(e)}<span>${esc(e.role)}</span><input type="checkbox" data-step-list="experts" value="${e.id}" ${s.experts.includes(e.id)?'checked':''}></label>`).join('')}</div><div class="inspector-group"><h3>Giới hạn thực hiện</h3><div class="two-fields"><label><span class="label">Vòng trao đổi tối đa</span><input type="number" id="step-rounds" data-step-field="rounds" min="0" max="5" value="${s.rounds}"></label><label><span class="label">Token / task</span><input type="number" id="step-budget" data-step-field="budget" min="100" step="1000" value="${s.budget}"></label></div><p class="small muted tiny-gap">Đánh giá đầu tiên độc lập; ${s.rounds} vòng phản biện tối đa sau đó. Không bắt buộc đồng thuận.</p></div><div class="inspector-group"><h3>Phụ thuộc</h3>${state.steps.filter(other=>other.id!==s.id).map(other=>`<label class="check"><input type="checkbox" data-step-list="depends" value="${other.id}" ${s.depends.includes(other.id)?'checked':''}>${other.id} · ${esc(other.title)}</label>`).join('')||'<p class="small muted">Chưa có bước khác.</p>'}</div><div class="inspector-group"><h3>Tài liệu riêng của bước</h3>${documents.map(d=>`<div class="between"><label class="check"><input type="checkbox" data-step-list="docs" value="${d.id}" ${s.docs.includes(d.id)?'checked':''}>${esc(d.name)}</label><button class="text-button" data-action="document" data-id="${d.id}">Xem</button></div>`).join('')}</div><div class="inspector-group"><h3>Context expert sẽ nhận</h3><div class="input-preview">• Vấn đề và đầu ra discussion<br>• Chỉ dẫn bước ${s.id} và skills của expert<br>• ${s.docs.length} tài liệu đã gán + ${state.discussionDocs.length} tài liệu hồ sơ<br>• ${s.depends.length?'Brief từ '+s.depends.join(', '):'Không có brief upstream'}<br>• ${state.selectedCases.length} case tham khảo đã chọn<br>• Ý kiến peer chỉ xuất hiện ở pha phản biện</div></div></aside>`;
}
function renderGuided(){return `<div class="guided-plan"><section class="guided-rail">${state.steps.map((s,i)=>`<button class="guided-step ${s.id===state.selectedStep?'selected':''}" data-action="select-step" data-id="${s.id}"><span class="section-number">${i+1}</span><div><h3>${esc(s.title)}</h3><p>${s.depends.length?'Sau '+s.depends.join(', '):'Bắt đầu độc lập'} · ${s.experts.length} expert</p></div></button>`).join('')}${btn(ico('plus')+' Thêm bước','add-step','small')}</section>${renderInspector()}</div>`;}
function renderMatrix(){return `<div class="matrix-layout"><div class="card matrix-card"><div class="canvas-toolbar"><strong>Phân công & phụ thuộc</strong>${btn(ico('plus')+' Thêm bước','add-step','small')}</div><table class="matrix"><thead><tr><th>Bước / phụ thuộc</th>${experts.map(e=>`<th title="${esc(e.role)}">${avatar(e)}<div style="margin-top:8px;font-size:9px">${esc(e.role)}</div></th>`).join('')}<th>Giới hạn</th></tr></thead><tbody>${state.steps.map(s=>`<tr tabindex="0" data-action="select-step" data-id="${s.id}" class="${s.id===state.selectedStep?'selected':''}"><td><div class="matrix-title">${s.id} · ${esc(s.title)}</div><p class="muted tiny-gap">${s.depends.length?'← '+s.depends.join(' + '):'Không phụ thuộc'}</p></td>${experts.map(e=>`<td class="matrix-role">${s.experts.includes(e.id)?'●':'<span style="color:#e1e6ee">—</span>'}</td>`).join('')}<td>${s.rounds} vòng<br><span class="muted">${s.budget.toLocaleString()} token</span></td></tr>`).join('')}</tbody></table><div class="canvas-legend">● Expert được giao · Chọn một dòng để chỉnh chi tiết</div></div>${renderInspector()}</div>`;}
function renderPlan(){return heading('03 / PLAN DESIGN','Biết rõ ai làm gì, với context nào.','Điều chỉnh plan của phiên này. Sau Start, người dùng theo dõi toàn bộ quy trình đến điểm kết thúc.')+planHeader()+(state.variant==='A'?`<div class="plan-layout">${renderDAG()}${renderInspector()}</div>`:state.variant==='B'?renderGuided():renderMatrix())+`<section class="card output-contract"><div class="between section-title"><h3>Đầu ra cuối cùng</h3>${state.mode==='custom'?badge('Template mới','purple'):btn(ico('plus')+' Lưu thành template mới','save-template','small')}</div><label class="screen-reader" for="plan-output">Đầu ra cuối cùng</label><textarea id="plan-output" data-field="output">${esc(state.output)}</textarea><div class="notice tiny-gap">Giới hạn vòng áp dụng theo từng bước. Khi không thể tiếp tục, phiên kết thúc rõ trạng thái và giữ các kết quả đã hoàn thành.</div>${state.validation?`<div class="plan-error" role="alert">${esc(state.validation)}</div>`:''}</section>${wizardFooter('Case liên quan','Review plan')}`;}
function renderReview(){const refs=[...new Set(state.steps.flatMap(s=>s.docs))];return heading('04 / READY TO START','Kiểm tra lần cuối.','Plan sẽ được cố định khi bắt đầu. Chỉ expert AI tham gia thực hiện.')+`<div class="review-layout"><div class="review-list">${[
  ['file','Vấn đề & đầu ra',`${state.title}\n${state.output}`,1],
  ['book','Case tham khảo',state.selectedCases.length?state.selectedCases.map(id=>cases.find(c=>c.id===id)?.title).filter(Boolean).join(' · '):'Không dùng case tham khảo',2],
  ['graph','Plan & phân công',`${state.steps.length} bước · ${selectedExpertCount()} expert · ${refs.length} tài liệu tham khảo riêng theo bước`,3]
].map(([icon,title,description,step])=>`<section class="card review-row"><span class="avatar">${ico(icon)}</span><div class="grow"><h3>${title}</h3><p>${esc(description)}</p></div><button class="text-button" data-action="wizard-goto" data-step="${step}">Chỉnh sửa</button></section>`).join('')}<section class="card"><div class="between section-title"><h3>Trình tự thực hiện</h3>${badge('Không sửa khi đang chạy')}</div>${state.steps.map(s=>`<div class="between" style="padding:11px 0;border-bottom:1px solid var(--line)"><div class="row"><span class="section-number">${s.id.slice(1)}</span><div><h3 class="small">${esc(s.title)}</h3><p class="muted" style="font-size:10px">${s.depends.length?'Sau '+s.depends.join(', '):'Không phụ thuộc'} · ${s.experts.length} expert · tối đa ${s.rounds} vòng trao đổi</p></div></div>${miniatureExperts(s.experts)}</div>`).join('')}</section></div><aside class="card review-side"><div class="eyebrow">EXECUTION CONTRACT</div><h3>Điểm kết thúc rõ ràng</h3><ul><li>Dừng trao đổi khi đạt giới hạn của từng bước.</li><li>Giữ nguyên các ý kiến còn khác nhau.</li><li>Nếu không thể tiếp tục, giữ kết quả đã có và chỉ rõ phần chưa hoàn tất.</li><li>Không chờ người phân xử hoặc thêm vòng trong lúc chạy.</li></ul><div class="notice amber">Trong prototype, Start mở luồng màn hình mẫu; không chạy model hoặc LangGraph.</div>${state.validation?`<div class="plan-error">${esc(state.validation)}</div>`:''}${btn('Start discussion '+ico('arrow'),'start','primary gap','style="width:100%"')}</aside></div>${wizardFooter('Plan & đầu ra','Start discussion','start')}`;}

function renderRunning(){
  const run=state.run,steps=run.plan.steps;
  return heading('DISCUSSION / RUNNING',esc(run.plan.title),'Plan đang được thực hiện. Bạn có thể xem tiến trình; không cần điều phối hoặc phân xử giữa các bước.',badge('Đang chạy · màn hình mẫu','red'))+`<div class="run-layout"><section class="card"><div class="between"><h2>Expert đang đánh giá độc lập</h2><span class="pulse"></span></div><div class="progress"><i style="width:12%"></i></div><div class="between muted small"><span>Bước 1 / ${steps.length}</span><span>Chưa có kết quả cuối cùng</span></div>${steps.map((s,i)=>`<article class="run-step"><span class="run-indicator ${i===0?'running':''}">${i===0?'<span class="pulse"></span>':i+1}</span><div class="grow"><div class="between"><h3>${esc(s.title)}</h3>${badge(i===0?'Đang đánh giá':'Đang chờ',i===0?'red':'')}</div><p>${i===0?'Các expert nhận context riêng. Ý kiến chưa được chia sẻ trước pha phản biện.':s.depends.length?'Chờ kết quả: '+s.depends.join(', '):'Chờ lượt thực hiện'}</p><div class="row tiny-gap">${miniatureExperts(s.experts)}<span class="small muted">${s.experts.length} expert · ${s.rounds} vòng tối đa</span></div></div></article>`).join('')}</section><aside class="stack"><section class="card"><div class="eyebrow">YOUR PLAN</div><h3>Đã cố định sau Start</h3><p class="small muted tiny-gap">${steps.length} bước · ${new Set(steps.flatMap(s=>s.experts)).size} expert</p><div class="divider"></div><h3 class="small">Quy tắc kết thúc</h3><p class="small muted tiny-gap">Không bắt buộc đồng thuận. Thoát rõ ràng nếu thiếu điều kiện để tiếp tục. Bảo toàn kết quả đã thực hiện.</p></section><section class="notice amber"><strong>Đây là storyboard frontend.</strong><br>Không có tác vụ thực thi trong nền. Dùng mục “Màn hình” trên thanh PROTOTYPE bên dưới để xem kết quả hoàn tất hoặc thoát sớm.</section></aside></div>`;
}
const sampleResults={
  C1:{rating:'HIGH',summary:'Nội dung truy xuất chưa có ranh giới tin cậy rõ ràng; cần kiểm soát prompt injection trước pilot.',dissent:'Security Expert giữ mức HIGH; AI Safety Expert cho rằng MODERATE phù hợp nếu bật kiểm soát nội dung. Bằng chứng triển khai kiểm soát chưa có.',evidence:[{doc:'D1',ref:'§1',quote:'Hệ thống nhận nội dung từ khách hàng và tài liệu đính kèm.'},{doc:'D2',ref:'§1',quote:'Nội dung không tin cậy không được thay đổi chính sách hoặc quyền thực thi.'}]},
  C2:{rating:'MODERATE',summary:'Cần bổ sung chính sách che dữ liệu khi logging và thời gian lưu giữ hồ sơ.',dissent:'Chưa có bất đồng trọng yếu trong dữ liệu mẫu.',evidence:[{doc:'D1',ref:'§2',quote:'Kết quả truy vấn có thể chứa dữ liệu nhận diện khách hàng.'},{doc:'D3',ref:'§2',quote:'Che dữ liệu nhạy cảm trước khi ghi log.'}]},
  C3:{rating:'HIGH',summary:'Service account dùng chung chưa thể hiện phân quyền theo người dùng cuối.',dissent:'Hai expert giữ mức HIGH; khác nhau về ưu tiên giảm thiểu.',evidence:[{doc:'D1',ref:'§3',quote:'Công cụ tra cứu hiện dùng service account có quyền dùng chung.'},{doc:'D2',ref:'§2',quote:'Quyền truy cập công cụ phải gắn với người dùng cuối.'}]},
  C4:{rating:'HIGH',summary:'Chỉ nên pilot sau khi bổ sung kiểm soát nội dung, phân quyền công cụ và xử lý dữ liệu.',dissent:'Bảo tồn bất đồng về C1 trong báo cáo; đây là kết luận AI mẫu, chưa được người thật phê duyệt.',evidence:[{doc:'D2',ref:'§3',quote:'Mỗi đánh giá phải có bằng chứng, giới hạn và biện pháp giảm thiểu.'}]}
};
function buildResult(step,index){
  const original=templateSteps().find(s=>s.id===step.id);
  const baseline=state.run?.plan.templateId==='ai-risk'&&original&&['title','instruction','output','experts','docs','depends'].every(key=>JSON.stringify(step[key])===JSON.stringify(original[key]));
  const sample=baseline?clone(sampleResults[step.id]):{rating:null,summary:'Đầu ra minh họa cho bước đã cấu hình. Prototype chưa sinh nội dung theo chỉ dẫn mới.',dissent:step.experts.length>1?'Có thể hiển thị các quan điểm khác nhau tại đây; chưa đánh giá thực tế.':'Một expert thực hiện; không có phản biện chéo.',evidence:[]};
  const permitted=new Set([...step.docs,...state.run.plan.discussionDocs]);
  sample.evidence=sample.evidence.filter(e=>permitted.has(e.doc));
  return {stepId:step.id,title:step.title,outputContract:step.output,...sample,rounds:step.rounds,experts:step.experts.map((id,i)=>({id,role:expertById(id)?.role||id,initial:baseline&&step.id==='C1'&&id==='safety'?'MODERATE':sample.rating,final:baseline&&step.id==='C1'&&id==='safety'?'MODERATE':sample.rating,view:i===0?'Ưu tiên bằng chứng về tác động và điều kiện kiểm soát.':'Ưu tiên các tình huống thất bại và ranh giới tin cậy.'})),index};
}
function finishFixture(scenario){
  const run=state.run;if(!run){toast('Hãy review và Start discussion trước.');return;}
  run.status=scenario==='partial'?'incomplete':'completed';run.results=[];
  const order=topologicalSteps(run.plan.steps);
  const count=scenario==='partial'?Math.max(0,Math.min(2,order.length-1)):order.length;
  order.slice(0,count).forEach((s,i)=>run.results.push(buildResult(s,i)));
  const stopped=order[count];
  run.exit=scenario==='partial'?{step:stopped?.id||null,reason:'Màn hình mẫu: hết ngân sách của task trước lần gọi kế tiếp. Không thực hiện các bước còn lại.',completed:run.results.map(r=>r.stepId),unexecuted:order.slice(count).map(s=>s.id)}:null;
  run.trace=[{time:'00:00',type:'plan_frozen',title:'Cố định bản plan',detail:`${run.plan.steps.length} bước; context và phân công được ghi nhận tại Start.`}];
  run.results.forEach((r,i)=>{
    run.trace.push({time:`00:${String(i*12+2).padStart(2,'0')}`,type:'assessment',step:r.stepId,title:`${r.stepId} · Đánh giá độc lập`,detail:`${r.experts.length} expert; ý kiến peer chưa được chia sẻ.`});
    if(r.experts.length>1)run.trace.push({time:`00:${String(i*12+5).padStart(2,'0')}`,type:'review',step:r.stepId,title:`${r.stepId} · Phản biện`,detail:`Dữ liệu minh họa; tối đa ${r.rounds} vòng trao đổi theo plan.`});
    run.trace.push({time:`00:${String(i*12+9).padStart(2,'0')}`,type:'commit',step:r.stepId,title:`${r.stepId} · Hoàn tất & tạo brief`,detail:'Lưu kết quả mẫu, bất đồng và nguồn liên quan.'});
  });
  run.trace.push({time:'01:00',type:run.status,title:run.status==='completed'?'Hoàn tất plan':'Thoát sớm · chưa hoàn tất',detail:run.exit?.reason||'Giữ nguyên bất đồng. Kết quả chưa được người thật phê duyệt.'});
  state.scenario=scenario;state.page='dashboard';state.dashTab='overview';if(!state.sessions.includes(run))state.sessions.push(run);render();window.scrollTo(0,0);
}
function topologicalSteps(steps){const done=new Set(),result=[];for(let i=0;i<steps.length;i++){const ready=steps.find(s=>!done.has(s.id)&&s.depends.every(id=>done.has(id)));if(!ready)break;done.add(ready.id);result.push(ready);}return result;}
function renderDashboard(){
  const run=state.run;if(!run)return '<div class="empty">Chưa có discussion.</div>';
  const complete=run.status==='completed',remaining=run.plan.steps.length-run.results.length;
  return heading('DISCUSSION / RESULTS',esc(run.plan.title),'Kết quả minh họa theo plan đã review. Mỗi kết luận có thể mở xuống ý kiến expert và tài liệu liên quan.',`<div class="row">${btn(ico('download')+' Xuất kết quả','export','small')}${btn(ico('link')+' Chia sẻ','share','small')}</div>`)+`<div class="notice ${complete?'green':'amber'}"><strong>${complete?'Plan đã hoàn tất':'Plan chưa hoàn tất'}</strong> · ${complete?'Các bất đồng được giữ nguyên; không đồng nghĩa với phê duyệt của người thật.':esc(run.exit.reason)} <span class="badge ${complete?'green':'amber'}">DỮ LIỆU MẪU</span></div><div class="metric-grid"><div class="card metric"><span class="label">Bước hoàn tất</span><strong>${run.results.length}<span class="muted" style="font-size:16px"> / ${run.plan.steps.length}</span></strong><span class="small muted">${remaining?remaining+' bước chưa thực hiện':'Đã đến điểm kết thúc'}</span></div><div class="card metric"><span class="label">Expert trong plan</span><strong>${new Set(run.plan.steps.flatMap(s=>s.experts)).size}</strong><span class="small muted">AI expert · theo phân công</span></div><div class="card metric"><span class="label">Ý kiến cần xem xét</span><strong>${run.results.filter(r=>r.experts.length>1).length}</strong><span class="small muted">Mở từng bước để đọc chi tiết</span></div><div class="card metric"><span class="label">Nguồn được trích dẫn</span><strong>${new Set(run.results.flatMap(r=>r.evidence.map(e=>e.doc))).size}</strong><span class="small muted">Có thể mở tài liệu gốc</span></div></div><nav class="dashboard-tabs" aria-label="Nội dung kết quả">${[['overview','Tổng quan'],['results','Kết quả từng bước'],['evidence','Bằng chứng'],['trace','Trace thực hiện'],['plan','Plan đã chạy']].map(([key,label])=>`<button class="tab ${state.dashTab===key?'active':''}" data-action="dash-tab" data-tab="${key}">${label}</button>`).join('')}</nav>${state.dashTab==='overview'?renderOverview():state.dashTab==='results'?renderResultTable():state.dashTab==='evidence'?renderEvidence():state.dashTab==='trace'?renderTrace():renderRunPlan()}`;
}
function renderOverview(){const run=state.run;return `<div class="review-layout"><div class="stack"><section class="card"><div class="eyebrow">EXECUTIVE SUMMARY · SAMPLE</div><h2>${run.status==='completed'?'Bức tranh tổng thể, với các ý kiến được giữ nguyên.':'Kết quả đến thời điểm thoát.'}</h2><p class="small muted gap">${run.results.length?esc(run.results.at(-1).summary):'Chưa có bước nào hoàn tất. Không có kết luận nghiệp vụ để sử dụng.'}</p>${run.exit?`<div class="notice amber gap">Chưa thực hiện: ${run.exit.unexecuted.map(id=>esc(run.plan.steps.find(s=>s.id===id)?.title||id)).join(', ')}. Không suy diễn kết luận cho các bước này.</div>`:''}<div class="divider"></div><h3>Các phát hiện đã ghi nhận</h3>${run.results.map(r=>`<div class="finding"><div class="between"><h3>${r.stepId} · ${esc(r.title)}</h3>${r.rating?badge(r.rating,r.rating==='HIGH'?'red':'amber'):badge('Nội dung mẫu')}</div><p>${esc(r.summary)}</p><button class="text-button" data-action="result-detail" data-id="${r.stepId}">Xem ý kiến & bằng chứng →</button></div>`).join('')||'<p class="small muted tiny-gap">Chưa có phát hiện.</p>'}</section>${renderResultTable()}</div><aside class="stack"><section class="card"><div class="eyebrow">PRESERVE DISSENT</div><h3>Bất đồng không bị san phẳng</h3><p class="small muted tiny-gap">${esc(run.results.find(r=>r.experts.length>1)?.dissent||'Chưa có ý kiến phản biện trong phần đã thực hiện.')}</p></section><section class="card"><h3>Đầu ra đã yêu cầu</h3><p class="small muted tiny-gap">${esc(run.plan.output)}</p><div class="divider"></div><h3>Tái sử dụng</h3><p class="small muted tiny-gap">Xuất JSON để giữ plan và trace; xuất Markdown để tiếp tục biên tập báo cáo.</p>${btn(ico('download')+' Xuất file','export','small gap')}</section></aside></div>`;}
function renderResultTable(){const run=state.run;return `<section class="card"><div class="between section-title"><h3>Kết quả theo từng bước</h3><span class="small muted">Chọn dòng để truy nguồn</span></div><div class="table-scroll"><table class="report-table"><thead><tr><th>Bước</th><th>Expert</th><th>Kết quả</th><th>Trạng thái</th></tr></thead><tbody>${run.plan.steps.map(s=>{const r=run.results.find(r=>r.stepId===s.id);return `<tr tabindex="0" data-action="${r?'result-detail':'unexecuted'}" data-id="${s.id}"><td><strong>${s.id} · ${esc(s.title)}</strong></td><td>${miniatureExperts(s.experts)}</td><td>${r?r.rating?badge(r.rating,r.rating==='HIGH'?'red':'amber'):badge('Đầu ra minh họa'):'—'}</td><td>${badge(r?'Hoàn tất':run.exit?.step===s.id?'Dừng tại đây':'Chưa thực hiện',r?'green':'amber')}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function renderEvidence(){const all=state.run.results.flatMap(r=>r.evidence.map(e=>({...e,step:r.stepId})));return `<section class="card"><h3>Bằng chứng được dẫn trong kết quả mẫu</h3>${all.map(e=>`<div class="evidence-row"><div class="between"><span class="row">${badge(e.step)}<strong class="small">${esc(currentDocument(e.doc)?.name)} · ${esc(e.ref)}</strong></span>${btn('Mở nguồn '+ico('arrow'),'document','small',`data-id="${e.doc}"`)}</div><p>“${esc(e.quote)}”</p></div>`).join('')||'<div class="empty">Chưa có trích dẫn. Prototype không tự tạo bằng chứng cho bước bạn vừa thêm hoặc chỉnh.</div>'}</section>`;}
function renderTrace(){return `<section class="card"><div class="between section-title"><h3>Lịch sử thực hiện</h3>${badge('Event mẫu · không phải log backend')}</div>${state.run.trace.map(t=>`<div class="trace-entry"><time>${t.time}</time><span class="trace-dot"></span><div><strong>${esc(t.title)}</strong><p>${esc(t.detail)}</p>${t.step?`<button class="text-button" data-action="result-detail" data-id="${t.step}">Mở artifact ${t.step} →</button>`:''}</div></div>`).join('')}</section>`;}
function renderRunPlan(run=state.run){return `<section class="card"><h3>Bản plan tại thời điểm Start</h3><p class="small muted tiny-gap">Các thay đổi trong discussion mới không sửa bản đã chạy.</p>${run.plan.steps.map(s=>`<article class="review-row" style="border-bottom:1px solid var(--line)"><span class="section-number">${s.id.slice(1)}</span><div class="grow"><h3>${esc(s.title)}</h3><p>${esc(s.instruction)}</p><p>${s.depends.length?'Upstream: '+s.depends.join(', '):'Không có upstream'} · ${s.rounds} vòng tối đa · ${s.budget.toLocaleString()} token/task</p><p>Đầu ra: ${esc(s.output)}</p><p>Expert: ${s.experts.map(id=>esc(run.plan.experts.find(e=>e.id===id)?.role||id)).join(', ')}</p><p>Tài liệu: ${s.docs.map(id=>esc(currentDocument(id)?.name||id)).join(', ')}</p></div></article>`).join('')}</section>`;}
function renderLibrary(){const list=cases.filter(c=>c.public&&(c.title+' '+c.description).toLowerCase().includes(state.caseQuery.toLowerCase()));return heading('KNOWLEDGE FROM PAST WORK','Case Library','Khám phá toàn bộ case được chia sẻ: bối cảnh, tài liệu, plan, ý kiến và kết quả.')+`<div class="library-toolbar"><div class="search-box">${ico('search')}<input id="case-search" data-field="caseQuery" value="${esc(state.caseQuery)}" placeholder="Tìm case đã chia sẻ…" aria-label="Tìm case"></div>${badge(list.length+' case public','green')}</div><div class="grid3">${list.map(c=>`<article class="card stack"><div class="between">${badge('Public','green')}<span class="muted small">${c.date}</span></div><h3>${esc(c.title)}</h3><p class="small muted">${esc(c.description)}</p><div class="notice">${esc(c.summary)}</div><div class="between"><span class="small muted">${esc(c.owner)}</span>${btn('Xem case','case','small',`data-id="${c.id}"`)}</div></article>`).join('')||'<div class="empty">Không tìm thấy case.</div>'}</div>`;}
const modalHistory=[];
function openModal(title,description,content,wide=false){
  const opener=document.activeElement;
  if($('#modal-root').firstElementChild)modalHistory.push({node:$('#modal-root').firstElementChild,opener:openModal.opener});
  $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(description)}</p></div><button class="btn small icon-btn" data-action="close-modal" aria-label="Đóng">${ico('close')}</button></div>${content}</section></div>`;
  openModal.opener=opener;$('#app').inert=true;$('#prototype-tools').inert=true;
  ($('input,textarea,select', $('#modal-root'))||$('button', $('#modal-root')))?.focus();
}
function closeModal(){if(!$('#modal-root').firstChild)return;const opener=openModal.opener;if(modalHistory.length){const previous=modalHistory.pop();$('#modal-root').replaceChildren(previous.node);openModal.opener=previous.opener;opener?.focus?.();return;}$('#modal-root').innerHTML='';$('#app').inert=false;$('#prototype-tools').inert=false;opener?.focus?.();}
function expertModal(id){
  const e=expertById(id);
  openModal(e?'Chỉnh sửa expert':'Tạo expert AI','Expert theo vai trò; danh tính cá nhân không bắt buộc.',`<form id="expert-form" data-id="${e?.id||''}"><div class="field"><label class="label" for="expert-role">Vai trò chuyên môn *</label><input id="expert-role" name="role" required value="${esc(e?.role||'') }" placeholder="Ví dụ: Model Risk Expert"></div><div class="field"><label class="label" for="expert-domain">Lĩnh vực</label><input id="expert-domain" name="domain" value="${esc(e?.domain||'AI & Data')}"></div><div class="field"><label class="label" for="expert-approach">Cách đánh giá</label><textarea id="expert-approach" name="approach" required placeholder="Ưu tiên bằng chứng nào? Cách lập luận và phản biện?">${esc(e?.approach||'')}</textarea></div><div class="field"><label class="label" for="expert-prompt">System instructions</label><textarea id="expert-prompt" name="prompt" placeholder="Phạm vi, nguyên tắc và điều expert cần tránh…">${esc(e?.prompt||'')}</textarea></div><div class="field"><span class="label">Skills được gắn</span>${skills.map(s=>`<div class="between"><label class="check"><input type="checkbox" name="skills" value="${esc(s.name)}" ${e?.skills.includes(s.name)?'checked':''}>${esc(s.name)}</label><button type="button" class="text-button" data-action="skill" data-name="${esc(s.name)}">Đọc</button></div>`).join('')}</div><div class="notice">Knowledge Base chưa triển khai. Các tài liệu tham khảo được gán trong plan.</div><div class="wizard-foot"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn primary" type="submit">${e?'Lưu thay đổi':'Tạo expert'}</button></div></form>`);
}
function resultModal(id,run=state.run){const r=run?.results.find(r=>r.stepId===id);if(!r){toast('Bước chưa có kết quả để xem.');return;}
  openModal(`${r.stepId} · ${r.title}`,'Artifact minh họa · ý kiến và trích dẫn không được sinh bởi model.',`<div class="notice">${esc(r.summary)}</div><h3 class="gap">Ý kiến expert · trước và sau phản biện</h3><div class="stack tiny-gap">${r.experts.map(e=>`<article class="card soft"><div class="between"><div class="row">${avatar(expertById(e.id))}<h3>${esc(e.role)}</h3></div><div class="row">${badge(e.initial||'Đầu ra mẫu')}<span class="muted">→</span>${badge(e.final||'Đầu ra mẫu')}</div></div><p class="small muted tiny-gap">${esc(e.view)} ${r.stepId==='C1'&&e.id==='safety'?'Giữ MODERATE với giả định kiểm soát nội dung được bật; bằng chứng xác nhận chưa có.':''}</p></article>`).join('')}</div><div class="notice amber gap"><strong>Bất đồng / giới hạn:</strong> ${esc(r.dissent)}</div><h3 class="gap">Bằng chứng liên quan</h3>${r.evidence.map(e=>`<div class="evidence-row"><button class="text-button" data-action="document" data-id="${e.doc}">${esc(currentDocument(e.doc)?.name)} · ${e.ref} ↗</button><p>“${esc(e.quote)}”</p></div>`).join('')||'<p class="small muted tiny-gap">Chưa có trích dẫn thực tế cho cấu hình này.</p>'}<div class="notice gap"><strong>Brief downstream:</strong> ${esc(r.summary)}<br><strong>Bất đồng còn mở:</strong> ${esc(r.dissent)}</div>`,true);
}
function documentModal(id){const doc=currentDocument(id);if(!doc)return;openModal(doc.name,`${doc.kind} · ${doc.id} · ${doc.metadataOnly?'chỉ có thông tin file':'nội dung mẫu / văn bản đọc cục bộ'}`,`<pre>${esc(doc.text)}</pre>`);}
function caseModal(id){const c=cases.find(c=>c.id===id);if(!c)return;if(c.run){openModal(c.title,'Case chia sẻ toàn bộ · bản frontend mẫu',`<div class="notice">${esc(c.summary)}</div><h3 class="gap">Bối cảnh</h3><p class="small muted tiny-gap">${esc(c.run.plan.star.situation)}</p><p class="small muted tiny-gap">${esc(c.run.plan.star.task)}<br>${esc(c.run.plan.star.action)}<br>${esc(c.run.plan.star.result)}</p><h3 class="gap">Đầu ra yêu cầu</h3><p class="small muted tiny-gap">${esc(c.run.plan.output)}</p><h3 class="gap">Plan và kết quả</h3>${renderRunPlan(c.run)}${c.run.results.map(r=>`<article class="card tiny-gap"><h3>${esc(r.title)}</h3><p class="small muted tiny-gap">${esc(r.summary)}</p><button class="text-button" data-action="case-result" data-case="${c.id}" data-id="${r.stepId}">Ý kiến & bằng chứng →</button></article>`).join('')}<h3 class="gap">Trace</h3><pre>${esc(JSON.stringify(c.run.trace,null,2))}</pre>${c.run.exit?`<div class="notice amber">${esc(c.run.exit.reason)}</div>`:''}<h3 class="gap">Tài liệu</h3><div class="row wrap tiny-gap">${c.docs.map(docChip).join('')}</div><div class="wizard-foot">${btn('Đóng','close-modal')}${btn(state.selectedCases.includes(c.id)?'Bỏ khỏi context':'Dùng làm context','case-from-modal','primary',`data-id="${c.id}"`)}</div>` ,true);return;}
  openModal(c.title,'Case public · toàn bộ nội dung có sẵn trong fixture',`<div class="row">${badge('Đã chia sẻ toàn bộ','green')}${badge(c.rating,'red')}</div><div class="gap"><h3>Bối cảnh & mục tiêu</h3><p class="small muted tiny-gap">${esc(c.description)}</p></div><div class="gap"><h3>Plan đã sử dụng</h3><ol class="small muted" style="line-height:2"><li>Đánh giá độc lập hồ sơ AutoSupport.</li><li>Phản biện có giới hạn giữa Safety và Security expert.</li><li>Tổng hợp kết quả và giữ lại bất đồng.</li></ol></div><div class="gap"><h3>Kết quả</h3><p class="small muted tiny-gap">${esc(c.summary)}</p></div><div class="gap"><h3>Ý kiến & phản biện</h3><p class="small muted tiny-gap">Safety Expert: cần kiểm chứng kiểm soát nội dung. Security Expert: cần ràng buộc quyền công cụ theo người dùng. Sau phản biện, cả hai giữ yêu cầu bổ sung bằng chứng trước pilot.</p></div><div class="gap"><h3>Tài liệu nguồn</h3><div class="row wrap tiny-gap">${c.docs.map(docChip).join('')}</div></div><div class="notice gap">Trace mẫu: nạp hồ sơ → đánh giá độc lập → phản biện → tổng hợp. Đây là toàn bộ case mẫu, không có transcript ẩn.</div><div class="wizard-foot">${btn('Đóng','close-modal')}${btn(state.selectedCases.includes(c.id)?'Bỏ khỏi context':'Dùng làm context','case-from-modal','primary',`data-id="${c.id}"`)}</div>`,true);
}
function exportObject(){return {prototype:true,execution:'frontend_fixture_only',runId:state.run.id,status:state.run.status,plan:state.run.plan,results:state.run.results,exit:state.run.exit,trace:state.run.trace,documents:documents.filter(d=>new Set([...state.run.plan.discussionDocs,...state.run.plan.steps.flatMap(s=>s.docs)]).has(d.id)),approvedByHuman:false};}
function download(format){if(!state.run)return;const data=exportObject();let text;
  if(format==='json')text=JSON.stringify(data,null,2);
  else text=`# ${data.plan.title}\n\n> FRONTEND PROTOTYPE — Dữ liệu minh họa, chưa được người thật phê duyệt.\n\nTrạng thái: ${data.status}\n\n## Đầu ra yêu cầu\n${data.plan.output}\n\n${data.exit?'## Thoát sớm\n'+data.exit.reason+'\nChưa thực hiện: '+data.exit.unexecuted.join(', ')+'\n\n':''}${data.results.map(r=>`## ${r.stepId} — ${r.title}\n${r.summary}\n\nBất đồng: ${r.dissent}\n\n${r.evidence.map(e=>`- ${e.doc}${e.ref}: ${e.quote}`).join('\n')}\n`).join('\n')}\n## Trace\n${data.trace.map(e=>`- ${e.time}: ${e.title} — ${e.detail}`).join('\n')}`;
  const url=URL.createObjectURL(new Blob([text],{type:format==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`dprism-${state.run.id}.${format==='json'?'json':'md'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất file dữ liệu mẫu.');
}
function renderTools(){const names={A:'DAG + Inspector',B:'Guided steps',C:'Expert matrix'};$('#prototype-tools').innerHTML=`<div class="prototype-bar" aria-label="Công cụ riêng của prototype"><span class="badge" style="background:#ffffff16;color:#fff;font-size:8px">PROTOTYPE</span><button data-action="variant-prev" aria-label="Cách xem trước">←</button><span class="bar-label">${state.variant} · ${names[state.variant]}</span><button data-action="variant-next" aria-label="Cách xem tiếp">→</button><span class="bar-divide"></span><select id="preview-state" aria-label="Xem màn hình mẫu"><option value="" selected>Màn hình mẫu</option><option value="running">Đang chạy</option><option value="complete">Hoàn tất</option><option value="partial">Thoát sớm</option></select><button data-action="toggle-state">${ico('settings')}<span class="bar-extra"> State</span></button><button data-action="reset" class="bar-extra">Đặt lại</button></div>${state.showState?`<aside class="state-drawer"><h3>State trong bộ nhớ · không có backend</h3><pre>${esc(JSON.stringify({...state,availableExperts:experts,availableSkills:skills,availableDocuments:documents},null,2))}</pre></aside>`:''}`;}
function setVariant(direction){const keys=['A','B','C'];state.variant=keys[(keys.indexOf(state.variant)+direction+3)%3];const url=new URL(location.href);url.searchParams.set('variant',state.variant);history.replaceState({},'',url);render();console.info('DPrism prototype state',clone(state));}
function go(page){state.page=page;state.validation='';render();window.scrollTo(0,0);}
function applyTemplate(id){state.templateId=id;state.steps=id==='ai-risk'?templateSteps():[
  {id:'C1',title:'Xác định tiêu chí so sánh',depends:[],experts:['safety','operations'],rounds:1,budget:10000,docs:['D1'],instruction:'Xác định các tiêu chí và ràng buộc từ hồ sơ AutoSupport.',output:'Danh sách tiêu chí và trọng số đề xuất'},
  {id:'C2',title:'So sánh phương án kiểm soát',depends:['C1'],experts:['security','operations'],rounds:2,budget:14000,docs:['D1','D2'],instruction:'So sánh phương án kiểm soát theo các tiêu chí upstream.',output:'Ma trận phương án, bằng chứng và trade-off'},
  {id:'C3',title:'Tổng hợp khuyến nghị',depends:['C2'],experts:['synthesizer'],rounds:0,budget:8000,docs:['D1'],instruction:'Tổng hợp lựa chọn, giới hạn và quan điểm khác nhau.',output:'Khuyến nghị và điều kiện thực hiện'}
];state.selectedStep='C1';state.output=id==='ai-risk'?'Bảng rủi ro theo cấu phần; executive summary; bằng chứng; bất đồng; biện pháp giảm thiểu; trace thực hiện.':'Ma trận so sánh phương án, trade-off, khuyến nghị và điều kiện triển khai.';}
function startNew(mode,templateId){state.mode=mode;state.wizard=1;state.validation='';state.recommendations=false;if(templateId)applyTemplate(templateId);go('setup');}
function handleAction(button){const action=button.dataset.action,id=button.dataset.id;
  if(action==='navigate')return go(button.dataset.page);
  if(action==='new-expert'||action==='expert-profile')return expertModal(id);
  if(action==='close-modal')return closeModal();
  if(action==='skill'){const s=skills.find(s=>s.name===button.dataset.name);return openModal(s.name,'SKILL.md mẫu · chỉ để đọc trong prototype',`<pre>${esc(s.content)}</pre>`);}
  if(action==='use-template')return startNew('template',id);
  if(action==='describe-template')return startNew('find');
  if(action==='open-discussion'){startNew('open');state.templateId=null;return;}
  if(action==='recommended-template'){applyTemplate(id);state.mode='template';state.wizard=2;render();window.scrollTo(0,0);return;}
  if(action==='custom-template'){state.mode='custom';state.templateId=null;state.steps=[{id:'C1',title:'Đánh giá vấn đề',depends:[],experts:[],rounds:1,budget:10000,docs:[],instruction:'',output:''}];state.selectedStep='C1';state.wizard=3;render();window.scrollTo(0,0);return;}
  if(action==='wizard-next'){
    if(state.wizard===1&&(!state.title.trim()||!state.star.task.trim()||!state.output.trim()))return toast('Cần tên discussion, mục tiêu và đầu ra mong muốn.');
    if(state.wizard===1&&state.mode==='find'){state.recommendations=true;render();return toast('Chọn một template hoặc tự tạo template mới ở phía dưới.');}
    if(state.wizard===2&&state.mode==='open'){
      const desiredOutput=state.output;applyTemplate('ai-risk');state.templateId=null;state.output=desiredOutput;toast('Plan đề xuất là fixture; chưa có AI phân tích chủ đề.');
    }
    if(state.wizard===3){state.validation=validatePlan();if(state.validation){render();return toast(state.validation);}}
    state.wizard=Math.min(4,state.wizard+1);render();window.scrollTo(0,0);return;
  }
  if(action==='wizard-back'){if(state.wizard===1)return go('templates');state.wizard--;render();window.scrollTo(0,0);return;}
  if(action==='wizard-goto'){state.wizard=Number(button.dataset.step);render();window.scrollTo(0,0);return;}
  if(action==='toggle-case'||action==='case-from-modal'){state.selectedCases=state.selectedCases.includes(id)?state.selectedCases.filter(x=>x!==id):[...state.selectedCases,id];if(action==='case-from-modal')closeModal();render();return;}
  if(action==='case')return caseModal(id);
  if(action==='case-result')return resultModal(id,cases.find(c=>c.id===button.dataset.case)?.run);
  if(action==='document')return documentModal(id);
  if(action==='select-step'){state.selectedStep=id;state.validation='';render();return;}
  if(action==='add-step'){const id='C'+(Math.max(0,...state.steps.map(s=>Number(s.id.slice(1))))+1);state.steps.push({id,title:'Bước mới',depends:state.steps.length?[state.steps.at(-1).id]:[],experts:[],rounds:1,budget:10000,docs:[],instruction:'',output:''});state.selectedStep=id;render();return;}
  if(action==='remove-step'){state.steps=state.steps.filter(s=>s.id!==id);state.steps.forEach(s=>s.depends=s.depends.filter(dep=>dep!==id));state.selectedStep=state.steps[0]?.id;render();return;}
  if(action==='save-template'){state.validation=validatePlan();if(state.validation){render();return toast(state.validation);}return openModal('Lưu thành template mới','Chỉ lưu trong bộ nhớ của prototype.',`<form id="template-form"><label class="label" for="template-name">Tên template</label><input id="template-name" name="name" required value="${esc(state.title)}"><div class="wizard-foot">${btn('Hủy','close-modal')}<button type="submit" class="btn primary">Lưu template</button></div></form>`);}
  if(action==='start'){
    state.validation=validatePlan();if(state.validation){render();return toast(state.validation);}
    if(state.mode==='custom'&&!state.templateId){const id='custom-'+Date.now();templates.push({id,title:state.title,description:'Template tự tạo trong prototype.',tag:'Custom',icon:'graph',steps:state.steps.length,output:state.output,definition:clone(state.steps)});state.templateId=id;}
    state.run={id:'run-'+Date.now().toString(36),status:'running',plan:clone({title:state.title,star:state.star,output:state.output,steps:state.steps,templateId:state.templateId,cases:state.selectedCases,discussionDocs:state.discussionDocs,experts:experts.filter(e=>state.steps.some(s=>s.experts.includes(e.id)))}),results:[],trace:[],exit:null,shared:false};return go('running');
  }
  if(action==='dash-tab'){state.dashTab=button.dataset.tab;render();return;}
  if(action==='result-detail')return resultModal(id);
  if(action==='unexecuted')return toast('Bước chưa được thực hiện; không có kết luận.');
  if(action==='export')return openModal('Xuất kết quả','File chứa nhãn prototype, trạng thái cuối và các phần đã hoàn thành.',`<div class="grid2"><button class="card path-card" data-action="download" data-format="json"><span class="avatar">${ico('file')}</span><div><h3>JSON</h3><p>Plan, artifacts, tài liệu, exit và trace.</p></div></button><button class="card path-card" data-action="download" data-format="md"><span class="avatar blue">${ico('file')}</span><div><h3>Markdown</h3><p>Báo cáo để tiếp tục biên tập.</p></div></button></div>`);
  if(action==='download')return download(button.dataset.format);
  if(action==='share')return openModal('Chia sẻ toàn bộ case','Trong prototype, case chia sẻ xuất hiện tại Case Library của phiên trình duyệt này.',`<div class="notice amber">Chia sẻ bao gồm bối cảnh, tài liệu tham khảo, plan, ý kiến expert, kết quả và trace. Không có quyền xem một phần trong MVP đã chốt.</div><div class="wizard-foot">${btn('Đóng','close-modal')}${btn(state.run.shared?'Đã chia sẻ ✓':'Chia sẻ case','confirm-share','primary',state.run.shared?'disabled':'')}</div>`);
  if(action==='confirm-share'){const r=state.run;r.shared=true;cases.push({id:'shared-'+r.id,title:r.plan.title,description:r.plan.star.task,owner:'Tran',date:'Vừa xong',rating:r.status==='completed'?'SAMPLE':'INCOMPLETE',summary:r.results.at(-1)?.summary||'Chưa có bước hoàn tất.',docs:[...new Set([...r.plan.discussionDocs,...r.plan.steps.flatMap(s=>s.docs)])],public:true,run:r});closeModal();render();return toast('Đã chia sẻ toàn bộ case trong phiên prototype.');}
  if(action==='session'){state.run=state.sessions[Number(button.dataset.index)];return go('dashboard');}
  if(action==='variant-prev')return setVariant(-1);
  if(action==='variant-next')return setVariant(1);
  if(action==='toggle-state'){state.showState=!state.showState;renderTools();return;}
  if(action==='reset')return location.reload();
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&!button.disabled)handleAction(button);if(event.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',event=>{
  if($('#modal-root').firstChild){
    if(event.key==='Escape')closeModal();
    if(event.key==='Tab'){const focusable=[...$('#modal-root').querySelectorAll('button,input,textarea,select,a[href]')].filter(e=>!e.disabled);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
    return;
  }
  if(event.target.closest('input,textarea,select,[contenteditable]'))return;
  if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();setVariant(event.key==='ArrowLeft'?-1:1);}
  if((event.key==='Enter'||event.key===' ')&&event.target.matches('tr[data-action]')){event.preventDefault();handleAction(event.target);}
});
document.addEventListener('input',event=>{const e=event.target;if(e.dataset.star)state.star[e.dataset.star]=e.value;if(e.dataset.field){state[e.dataset.field]=e.value;if(['expertQuery','caseQuery'].includes(e.dataset.field))render();}if(e.dataset.stepField){const s=stepById(state.selectedStep);s[e.dataset.stepField]=e.type==='number'?Number(e.value):e.value;}if(state.showState)renderTools();});
document.addEventListener('change',async event=>{
  const e=event.target;
  if(e.dataset.stepList){const s=stepById(state.selectedStep),key=e.dataset.stepList;s[key]=e.checked?[...s[key],e.value]:s[key].filter(x=>x!==e.value);if(key==='experts'&&s.experts.length>1&&s.rounds===0)s.rounds=1;state.validation=validatePlan();render();}
  if(e.dataset.stepField)render();
  if(e.dataset.actionChange==='domain'){state.expertDomain=e.value;render();}
  if(e.id==='preview-state'){
    if(!state.run){toast('Review và Start một discussion để xem các trạng thái mẫu.');e.value='';return;}
    if(e.value==='running'){state.run.status='running';go('running');}else if(e.value)finishFixture(e.value);
  }
  if(e.id==='document-upload'){
    for(const file of e.files){const isText=/\.(txt|md|csv)$/i.test(file.name),id='U'+(documents.filter(d=>d.id.startsWith('U')).length+1);documents.push({id,name:file.name,kind:'Tài liệu tải lên',metadataOnly:!isText,text:isText?await file.text():'Chưa trích xuất nội dung trong frontend prototype. File: '+file.name});state.discussionDocs.push(id);}
    render();toast('Đã thêm tài liệu vào hồ sơ của phiên này.');
  }
});
document.addEventListener('submit',event=>{
  if(event.target.id==='expert-form'){
    event.preventDefault();const form=new FormData(event.target),id=event.target.dataset.id,role=form.get('role').trim(),domain=form.get('domain').trim()||'General';
    const data={role,domain,approach:form.get('approach').trim(),prompt:form.get('prompt').trim(),skills:form.getAll('skills'),initials:role.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(),color:'purple'};
    if(id)Object.assign(expertById(id),data);else experts.push({id:'expert-'+Date.now().toString(36),...data});closeModal();render();toast(id?'Đã cập nhật expert.':'Expert đã sẵn sàng để gán vào plan.');
  }
  if(event.target.id==='template-form'){
    event.preventDefault();const name=new FormData(event.target).get('name').trim(),id='template-'+Date.now();templates.push({id,title:name,description:'Template lưu từ bản plan đang chỉnh. Chỉ tồn tại trong phiên prototype.',tag:'Custom',icon:'graph',steps:state.steps.length,output:state.output,definition:clone(state.steps)});closeModal();render();toast('Đã lưu template mới trong bộ nhớ.');
  }
});
// Preserve the selected custom template definition when starting a new discussion.
const originalApplyTemplate=applyTemplate;
applyTemplate=function(id){const t=templates.find(t=>t.id===id);if(t?.definition){state.templateId=id;state.steps=clone(t.definition);state.selectedStep=state.steps[0].id;state.output=t.output;}else originalApplyTemplate(id);};
render();
